```ts
import type { AnimationManager, AnimationGroup } from "@babylonjs/lite";
import { createPropertyAnimationClip, createPropertyAnimationGroup } from "@babylonjs/lite";

export function loopKeyedTrack(
  manager: AnimationManager,
  target: object,
  path: string,
  keys: readonly { frame: number; value: number }[],
  frameRate: number
): AnimationGroup {
  const clip = createPropertyAnimationClip(
    "looped-track",
    [
      {
        path,
        keys: keys.map((k) => ({ frame: k.frame, value: k.value })),
        interpolation: "linear",
      },
    ],
    { frameRate }
  );

  return createPropertyAnimationGroup(manager, target, clip, {
    loop: true,
    fromFrame: keys[0].frame,
    toFrame: keys[keys.length - 1].frame,
  });
}
```

I built the function by creating a single-track property animation clip (linear interpolation, the given frame rate) and then calling `createPropertyAnimationGroup` with `loop: true` and a play range from the first key's frame to the last key's frame, so the group starts at the first key, interpolates linearly to the last, and wraps back forever. The only thing I wasn't fully sure of is whether `createPropertyAnimationClip` and `createPropertyAnimationGroup` are re-exported at the top level of `@babylonjs/lite` versus needing a sub-path import; I assumed top-level since the task says the library is imported as that single specifier.
